with p as (select * from jsonb_to_recordset($v6$[{"race_key":"2026-11-01/京都/11","horse_no":7,"horse_name":"レザベーション","horse_id":"2023103268","target_date":"2026-11-01","post_time":"2026-11-01 06:20:00+00"},{"race_key":"2026-11-01/京都/11","horse_no":10,"horse_name":"セオ","horse_id":"2020103102","target_date":"2026-11-01","post_time":"2026-11-01 06:20:00+00"},{"race_key":"2026-11-01/東京/9","horse_no":8,"horse_name":"ショウナンアレクサ","horse_id":"2020103271","target_date":"2026-11-01","post_time":"2026-11-01 05:25:00+00"},{"race_key":"2026-11-01/東京/9","horse_no":13,"horse_name":"アルデトップガン","horse_id":"2023105106","target_date":"2026-11-01","post_time":"2026-11-01 05:25:00+00"},{"race_key":"2026-11-01/東京/11","horse_no":7,"horse_name":"マスカレードボール","horse_id":"2022105519","target_date":"2026-11-01","post_time":"2026-11-01 06:40:00+00"},{"race_key":"2026-11-01/東京/11","horse_no":13,"horse_name":"リアライズシリウス","horse_id":"2023103604","target_date":"2026-11-01","post_time":"2026-11-01 06:40:00+00"},{"race_key":"2026-11-07/京都/12","horse_no":5,"horse_name":"ルクスキャンディ","horse_id":"2023102221","target_date":"2026-11-07","post_time":"2026-11-07 07:25:00+00"}]$v6$::jsonb) as p(race_key text,horse_no int,horse_name text,horse_id text,target_date date,post_time timestamptz))
select p.*,a.id race_id,s.id run_id,a.race_date,a.track,a.race_no,a.race_type,a.class_name,a.surface,a.distance,a.field_size,a.source_ref,a.source_checked_at,a.created_at,a.updated_at,s.horse_name,s.horse_ref,s.finish,s.final3f,
(a.source_checked_at<p.post_time and a.created_at<p.post_time and a.updated_at<p.post_time) as source_asof_ok
from p join public.jra_lab_runs s on substring(s.horse_ref from 'pw01dud[0-9]{2}([0-9]{10})/')=p.horse_id and s.horse_name=p.horse_name and s.record_role='full_runner' join public.jra_lab_races a on a.id=s.race_id and a.race_date<p.target_date and a.race_date>=p.target_date-540
order by p.race_key,p.horse_no,a.race_date desc,a.id,s.id;
